"""
Payment API Server — REST endpoints that simulate a real payment gateway.
Endpoints:
  POST /payments/initiate          ← Start a new payment
  POST /payments/{id}/authorize    ← Authorize it
  POST /payments/{id}/capture      ← Capture (charge the customer)
  POST /payments/{id}/settle       ← Settle with the bank
  POST /payments/{id}/refund       ← Refund
  POST /payments/{id}/fail         ← Mark as failed

  GET  /payments/{id}/events       ← Get all events for a payment
  GET  /payments/stream            ← Server-sent events (live feed)
  GET  /debug/problems             ← Live problem report
  GET  /debug/stats                ← Full system stats
  GET  /health                     ← Health check
"""

import json
import logging
import queue
import threading
import time
import uuid
from datetime import datetime, timezone
from typing import Dict

from flask import Flask, Response, jsonify, request, stream_with_context
from flask_cors import CORS

from models.event import PaymentEvent, PaymentStatus
from payment_api.event_store import store
from payment_api.payment_processor import processor, side_effects

logger = logging.getLogger("api.server")
app    = Flask(__name__)
CORS(app)

# ── SSE broadcast queue ───────────────────────────────────────
_sse_clients: list = []
_sse_lock = threading.Lock()


def _broadcast(event_type: str, data: dict):
    msg = f"event: {event_type}\ndata: {json.dumps(data)}\n\n"
    with _sse_lock:
        dead = []
        for q in _sse_clients:
            try:
                q.put_nowait(msg)
            except Exception:
                dead.append(q)
        for q in dead:
            _sse_clients.remove(q)


def _make_event(payment_id: str, seq: int,
                status: PaymentStatus, amount: int,
                currency: str, merchant: str) -> PaymentEvent:
    return PaymentEvent(
        event_id        = str(uuid.uuid4()),
        payment_id      = payment_id,
        sequence_number = seq,
        status          = status,
        amount_cents    = amount,
        currency        = currency,
        merchant_id     = merchant,
        event_time      = datetime.now(timezone.utc),
    )


# ── Payment lifecycle state tracker (in-memory) ──────────────
_payments: Dict[str, dict] = {}
_pay_lock = threading.Lock()


# ── API Endpoints ─────────────────────────────────────────────

@app.route("/health")
def health():
    return jsonify({"status": "ok", "ts": datetime.now(timezone.utc).isoformat()})


@app.route("/payments/initiate", methods=["POST"])
def initiate():
    body        = request.get_json(force=True)
    payment_id  = f"PAY-{str(uuid.uuid4())[:8].upper()}"
    amount      = body.get("amount_cents", 5000)
    currency    = body.get("currency", "USD")
    merchant    = body.get("merchant_id", "MERCH-001")

    event = _make_event(payment_id, 1, PaymentStatus.INITIATED,
                        amount, currency, merchant)

    with _pay_lock:
        _payments[payment_id] = {
            "seq": 1, "amount": amount,
            "currency": currency, "merchant": merchant,
            "status": "INITIATED",
        }

    result = processor.process_batch_with_chaos([event])
    _broadcast("payment_event", {**event.to_dict(), "chaos_result": result})

    return jsonify({
        "payment_id": payment_id,
        "status":     "INITIATED",
        "problems":   result["extra_events"],
        "detail":     result,
    }), 201


@app.route("/payments/<payment_id>/authorize", methods=["POST"])
def authorize(payment_id: str):
    with _pay_lock:
        pay = _payments.get(payment_id)
    if not pay:
        return jsonify({"error": "Payment not found"}), 404

    pay["seq"] += 1
    event = _make_event(payment_id, pay["seq"], PaymentStatus.AUTHORIZED,
                        pay["amount"], pay["currency"], pay["merchant"])

    result = processor.process_batch_with_chaos([event])
    pay["status"] = "AUTHORIZED"
    _broadcast("payment_event", {**event.to_dict(), "chaos_result": result})

    return jsonify({"payment_id": payment_id, "status": "AUTHORIZED",
                    "chaos_injected": result["extra_events"]})


@app.route("/payments/<payment_id>/capture", methods=["POST"])
def capture(payment_id: str):
    with _pay_lock:
        pay = _payments.get(payment_id)
    if not pay:
        return jsonify({"error": "Payment not found"}), 404

    pay["seq"] += 1
    event = _make_event(payment_id, pay["seq"], PaymentStatus.CAPTURED,
                        pay["amount"], pay["currency"], pay["merchant"])

    result = processor.process_batch_with_chaos([event])
    pay["status"] = "CAPTURED"
    _broadcast("payment_event", {**event.to_dict(), "chaos_result": result})

    charges = side_effects.charge_count_for(payment_id)
    return jsonify({
        "payment_id":    payment_id,
        "status":        "CAPTURED",
        "times_charged": charges,
        "double_charge": charges > 1,
        "chaos_injected": result["extra_events"],
    })


