@app.route("/payments/<payment_id>/events")
def get_events(payment_id: str):
    with store._db_lock:
        rows = store._conn.execute(
            "SELECT * FROM raw_events WHERE payment_id=? ORDER BY row_id",
            (payment_id,),
        ).fetchall()
    return jsonify({
        "payment_id":  payment_id,
        "event_count": len(rows),
        "events":      [dict(r) for r in rows],
        "duplicates":  sum(1 for r in rows if rows.count(r) > 1),
    })


@app.route("/debug/problems")
def debug_problems():
    dups        = store.count_duplicates()
    ooo         = store.detect_out_of_order()
    gaps        = store.detect_gaps()
    bad_states  = store.detect_invalid_states()
    amt_issues  = store.count_amount_mismatches()
    recent_prbs = store.get_recent_problems(20)
    se_summary  = side_effects.summary()

    return jsonify({
        "summary": {
            "duplicates_in_db":       dups,
            "out_of_order_payments":  len(ooo),
            "gap_payments":           len(gaps),
            "invalid_state_chains":   len(bad_states),
            "amount_corruptions":     amt_issues,
            "double_charges":         se_summary["double_charges"],
            "duplicate_notifications": se_summary["total_emails"] - len(
                {e["payment_id"] + e["status"] for e in side_effects.emails}
            ),
        },
        "out_of_order":    ooo[:10],
        "gaps":            gaps[:10],
        "invalid_states":  bad_states[:10],
        "recent_problems": recent_prbs,
        "side_effects":    se_summary,
        "chaos_stats":     processor.chaos_stats,
    })


@app.route("/debug/stats")
def debug_stats():
    return jsonify({
        "db_counts":       store.table_counts(),
        "chaos_stats":     processor.chaos_stats,
        "side_effects":    side_effects.summary(),
        "total_processed": processor.processed_count,
        "payments_tracked": len(_payments),
    })


@app.route("/payments/stream")
def payment_stream():
    """Server-Sent Events — live event feed for the dashboard."""
    q: queue.Queue = queue.Queue(maxsize=200)
    with _sse_lock:
        _sse_clients.append(q)

    def generate():
        yield "data: {\"type\": \"connected\"}\n\n"
        while True:
            try:
                msg = q.get(timeout=15)
                yield msg
            except queue.Empty:
                yield ": heartbeat\n\n"

    return Response(
        stream_with_context(generate()),
        mimetype="text/event-stream",
        headers={"Cache-Control": "no-cache", "X-Accel-Buffering": "no"},
    )
